/* Страница «Решения»: появление блоков, счётчик разделов, форма заявки.
   Без зависимостей: GSAP и Lenis на этой странице не нужны. */
(window.i18n ? window.i18n.ready : Promise.resolve()).then(() => {
  'use strict';
  /* i18n:ru begin (generated by tools/i18n/embed.mjs from i18n/ru.json: the Russian text of the messages this script shows; do not edit) */
  const RU = (() => {
    const nf = new Intl.NumberFormat('ru', { useGrouping: 'always' });
    const n = (x, d) => (d === undefined ? nf : new Intl.NumberFormat('ru', { useGrouping: 'always', minimumFractionDigits: d, maximumFractionDigits: d })).format(x);
    return {
      n,
      m: {
        'js.solutions.errors.name': () => 'Напишите, как к вам обращаться.',
        'js.solutions.errors.phone': () => 'Укажите телефон полностью: +7 и десять цифр.',
        'js.solutions.errors.contact': () => 'Укажите телефон или e-mail.',
        'js.solutions.errors.email': () => 'Проверьте e-mail: нужен вид name@company.ru.',
        'js.solutions.errors.consent': () => 'Нужно согласие на обработку данных.',
        'js.solutions.status.offline': () => 'Нет соединения с интернетом. Проверьте сеть и <button>повторите</button>.',
        'js.solutions.status.failed': () => 'Не удалось отправить заявку. <button>Повторить</button>',
      },
    };
  })();
  // N: a number as the site writes it in the current language; t: a message, English from the dictionary, else Russian from RU
  const N = (x, d) => (i18n.n || RU.n)(x, d);
  const t = (key, v) => { const s = i18n.t(key, v); return s === undefined ? RU.m[key](v) : s; };
  /* i18n:ru end */

  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

  // ---------- Бесконечные CSS-анимации вне экрана — на паузу (то же в main.js) ----------
  // Иначе браузер считает их каждый кадр, даже когда секция далеко за экраном: на телефоне это заметно.
  if (window.IntersectionObserver) {
    const io = new IntersectionObserver((list) => list.forEach((e) => e.target.classList.toggle('anim-off', !e.isIntersecting)), { rootMargin: '200px 0px' });
    document.querySelectorAll('section, footer').forEach((s) => io.observe(s));
  }

  // ---------- Reveal ----------
  const revealEls = [...document.querySelectorAll('.reveal')];
  const show = (el) => { el.style.opacity = '1'; el.style.transform = 'none'; };
  if (reduce || !('IntersectionObserver' in window)) {
    revealEls.forEach(show);
  } else {
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) { show(e.target); io.unobserve(e.target); } });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.05 });
    revealEls.forEach((el) => io.observe(el));
  }

  // ---------- Счётчик разделов ----------
  const counter = document.querySelector('.counter');
  const sections = [...document.querySelectorAll('[data-sec]')];
  if (counter && sections.length) {
    const cur = counter.querySelector('.cur');
    const lbl = counter.querySelector('.lbl');
    const bar = counter.querySelector('.bar i');
    let active = null;
    const sync = () => {
      const mid = window.innerHeight * 0.5;
      const sec = sections.reduce((acc, s) => (s.getBoundingClientRect().top <= mid ? s : acc), sections[0]);
      if (sec === active) return;
      active = sec;
      cur.textContent = sec.dataset.sec;
      lbl.textContent = sec.dataset.name;
      bar.style.transition = 'transform .6s var(--ease)';
      bar.style.transform = `scaleY(${+sec.dataset.sec / sections.length})`;
    };
    addEventListener('scroll', sync, { passive: true });
    addEventListener('resize', sync);
    sync();
  }

  // ---------- Форма ----------
  const form = document.getElementById('lead-form');
  if (!form) return;

  const els = {
    name: form.elements.namedItem('name'),
    phone: form.elements.namedItem('phone'),
    consent: form.elements.namedItem('consent'),
    website: form.elements.namedItem('website'),
    direction: form.elements.namedItem('direction'),
    // Страница «Контакты»: достаточно телефона или e-mail, плюс необязательные поля. На остальных страницах этих полей нет.
    email: form.elements.namedItem('email'),
    company: form.elements.namedItem('company'),
    intent: form.elements.namedItem('intent'),
    object: form.elements.namedItem('object'),
    task: form.elements.namedItem('task'),
  };
  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  const status = document.getElementById('f-status');
  const submitBtn = form.querySelector('button[type="submit"]');

  // Маска телефона: +7 (XXX) XXX-XX-XX
  const formatPhone = (raw) => {
    let d = raw.replace(/\D/g, '');
    if (d.startsWith('8') || d.startsWith('7')) d = d.slice(1);
    d = d.slice(0, 10);
    if (!d) return '';
    let out = '+7 (' + d.slice(0, 3);
    if (d.length >= 3) out += ')';
    if (d.length > 3) out += ' ' + d.slice(3, 6);
    if (d.length > 6) out += '-' + d.slice(6, 8);
    if (d.length > 8) out += '-' + d.slice(8, 10);
    return out;
  };
  els.phone.addEventListener('input', (e) => {
    // Не трогаем ввод при удалении: иначе маска «залипает» на скобках
    if (e.inputType && e.inputType.startsWith('delete')) return;
    els.phone.value = formatPhone(els.phone.value);
  });

  const setError = (input, message) => {
    const fld = input.closest('.fld');
    const err = document.getElementById(input.getAttribute('aria-describedby'));
    if (message) {
      fld.setAttribute('data-invalid', '');
      input.setAttribute('aria-invalid', 'true');
      err.textContent = message;
    } else {
      fld.removeAttribute('data-invalid');
      input.removeAttribute('aria-invalid');
      err.textContent = '';
    }
  };

  const validate = () => {
    const name = els.name.value.trim();
    const phoneDigits = els.phone.value.replace(/\D/g, '');
    const errors = [];
    const nameErr = name.length < 2 ? t('js.solutions.errors.name') : '';
    let phoneErr = phoneDigits.length !== 11 ? t('js.solutions.errors.phone') : '';
    let emailErr = '';
    if (els.email) {
      const email = els.email.value.trim();
      // Телефон или e-mail: пустой телефон не ошибка, если указан e-mail; начатый, но неполный телефон остаётся ошибкой
      if (!phoneDigits.length) phoneErr = email ? '' : t('js.solutions.errors.contact');
      if (email && !EMAIL_RE.test(email)) emailErr = t('js.solutions.errors.email');
    }
    const consentErr = els.consent.checked ? '' : t('js.solutions.errors.consent');
    setError(els.name, nameErr);
    setError(els.phone, phoneErr);
    if (els.email) setError(els.email, emailErr);
    setError(els.consent, consentErr);
    if (nameErr) errors.push(els.name);
    if (phoneErr) errors.push(els.phone);
    if (emailErr) errors.push(els.email);
    if (consentErr) errors.push(els.consent);
    return errors;
  };

  const invalidNow = (i) => i.closest('.fld').hasAttribute('data-invalid');
  // Телефон и e-mail проверяются вместе: набрав один, человек снимает ошибку «нужен хотя бы один»
  [els.name, els.phone, els.email].filter(Boolean).forEach((i) => i.addEventListener('input', () => {
    if (invalidNow(i) || (els.email && (i === els.phone || i === els.email) && (invalidNow(els.phone) || invalidNow(els.email)))) validate();
  }));
  els.consent.addEventListener('change', () => { if (els.consent.getAttribute('aria-invalid')) validate(); });

  const setStatus = (kind, html) => { status.dataset.kind = kind; status.innerHTML = html; };

  const send = async () => {
    const phoneDigits = els.phone.value.replace(/\D/g, '');
    const payload = {
      name: els.name.value.trim(),
      phone: phoneDigits ? '+' + phoneDigits : null,
      // На «О компании» списка направлений нет
      direction: (els.direction && els.direction.value) || null,
      // Отраслевые лендинги переиспользуют этот скрипт и задают свой источник (с якорем направления)
      source: form.dataset.source || 'solutions',
    };
    for (const k of ['email', 'company', 'intent', 'object', 'task']) if (els[k]) payload[k] = els[k].value.trim() || null;
    const endpoint = form.dataset.endpoint;
    // Пока бэкенда нет, прототип имитирует ответ. Заявка никуда не уходит.
    if (!endpoint) {
      console.info('[solutions] заявка (прототип, не отправлена):', payload);
      await new Promise((r) => setTimeout(r, 700));
      return;
    }
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 12000);
    try {
      const res = await fetch(endpoint, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload), signal: ctrl.signal,
      });
      if (!res.ok) throw new Error('HTTP ' + res.status);
    } finally {
      clearTimeout(timer);
    }
  };

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    if (form.classList.contains('is-busy')) return;
    setStatus('', '');

    // Honeypot: бот заполнил скрытое поле. Делаем вид, что всё хорошо.
    if (els.website.value) { form.classList.add('is-done'); return; }

    const invalid = validate();
    if (invalid.length) { invalid[0].focus(); return; }

    if (!navigator.onLine) {
      setStatus('error', t('js.solutions.status.offline').replace('<button>', '<button type="button" data-retry>'));
      return;
    }

    form.classList.add('is-busy');
    submitBtn.disabled = true;
    try {
      await send();
      form.classList.add('is-done');
    } catch (err) {
      setStatus('error', t('js.solutions.status.failed').replace('<button>', '<button type="button" data-retry>'));
    } finally {
      form.classList.remove('is-busy');
      submitBtn.disabled = false;
    }
  });

  status.addEventListener('click', (e) => {
    if (e.target.closest('[data-retry]')) form.requestSubmit();
  });
});
